//--------------------------------------------------------------------------------------//

void dei_temp_rx_fiq( void )
{
	if( gpio_pl_int_stat_f(GPIO_PL_TEMP_SENSOR) )
    {        
			gpio_pl_rising_irq_dis(GPIO_PL_TEMP_SENSOR);
			gpio_pl_falling_irq_dis(GPIO_PL_TEMP_SENSOR);
			gpio_pl_int_clr(GPIO_PL_TEMP_SENSOR);


			dei_temp_vars.edge = DEI_TEMP_FALLING_EDGE ;

			irq_user_trigger();
    }
	else
	{
		if( gpio_pl_int_stat_r(GPIO_PL_TEMP_SENSOR) )
	    {        
				gpio_pl_rising_irq_dis(GPIO_PL_TEMP_SENSOR);
				gpio_pl_falling_irq_dis(GPIO_PL_TEMP_SENSOR);
				gpio_pl_int_clr(GPIO_PL_TEMP_SENSOR);

				dei_temp_vars.edge = DEI_TEMP_RISING_EDGE ;

				irq_user_trigger();
	    }
	}    
} 

